query Neo4jInstanceList($pageNumber: Int, $limit: Int, $statuses: [String]) {
  neo4jInstanceList(pageNumber: $pageNumber, limit: $limit, statuses: $statuses) {
    neo4jInstanceList {
      partitionKey
      instanceId
      neo4jUri
      neo4jUsername
      neo4jDatabase
      status
      maxConnectionPoolSize
      createdAt
      updatedAt
    }
  }
}

mutation DeleteNeo4jInstance($partitionKey: String!, $instanceId: String!) {
  deleteNeo4jInstance(partitionKey: $partitionKey, instanceId: $instanceId)
}

query GraphSchemaList(
  $pageNumber: Int
  $limit: Int
  $schemaType: String
  $statuses: [String]
) {
  graphSchemaList(
    pageNumber: $pageNumber
    limit: $limit
    schemaType: $schemaType
    statuses: $statuses
  ) {
    graphSchemaList {
      partitionKey
      schemaName
      schemaType
      neo4jSchemaString
      status
      createdAt
      updatedAt
    }
  }
}

mutation DeleteGraphSchema($partitionKey: String!, $schemaName: String!) {
  deleteGraphSchema(partitionKey: $partitionKey, schemaName: $schemaName)
}

mutation DeleteDocument($partitionKey: String!, $documentUuid: String!) {
  deleteDocument(partitionKey: $partitionKey, documentUuid: $documentUuid)
}

