query Search(
  $queryText: String!
  $searchMode: String
  $schemaName: String
  $topK: Int
) {
  search(
    queryText: $queryText
    searchMode: $searchMode
    schemaName: $schemaName
    topK: $topK
  ) {
    results
    query
    total
    page
    limit
  }
}

